/**
 * ui.js
 *
 * Interface strings, one block per language. Same shape as manual.js so there
 * is only one mental model for translations in this codebase.
 *
 * Rules that keep this maintainable:
 *   - Keys are grouped by screen, never by English wording, so re-wording a
 *     button does not orphan its translations.
 *   - {placeholders} are filled by translate(); never build a sentence by
 *     concatenating fragments, because word order differs in Tamil.
 *   - English is the source of truth. `npm run i18n:check` lists every key
 *     English has that another language does not.
 */

